{
  "name": "whoami",
  "version": "0.1.0",
  "description": "Claude Code mod: shows which Claude account, organization and plan the session uses and how much of the usage limit is left, and holds prompts in a folder pinned to another account.",
  "author": {
    "name": "tornikegomareli",
    "url": "https://github.com/tornikegomareli"
  },
  "repository": "https://github.com/tornikegomareli/claude-whoami",
  "supportUrl": "https://github.com/tornikegomareli/claude-whoami/issues",
  "documentationUrl": "https://github.com/tornikegomareli/claude-whoami#readme",
  "license": "MIT",
  "keywords": [
    "account",
    "organization",
    "login",
    "usage",
    "rate-limit",
    "footer"
  ],
  "userConfig": {
    "fiveHourLimit": {
      "type": "boolean",
      "title": "Show the 5-hour limit",
      "description": "On: the footer shows how much of the 5-hour usage limit is used, and when it resets.",
      "default": true
    },
    "weeklyLimit": {
      "type": "string",
      "title": "Show the weekly limit",
      "description": "always: the footer always shows the weekly usage limit. over-half: only once it is 50% used. never: it is not shown.",
      "default": "over-half",
      "options": [
        "over-half",
        "always",
        "never"
      ]
    }
  }
}
